import{_ as e,o as a,c as o,a7 as n}from"./chunks/framework.C4ZIv4ii.js";const m=JSON.parse('{"title":"bKash & Nagad (Pro)","description":"","frontmatter":{},"headers":[],"relativePath":"ecommerce/bd-payments.md","filePath":"ecommerce/bd-payments.md","lastUpdated":1794409716000}'),r={name:"ecommerce/bd-payments.md"};function s(d,t,h,i,l,c){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="bkash-nagad-pro" tabindex="-1">bKash &amp; Nagad (Pro) <a class="header-anchor" href="#bkash-nagad-pro" aria-label="Permalink to &quot;bKash &amp; Nagad (Pro)&quot;">​</a></h1><p><strong>Falcon Bangladesh Payments</strong> adds bKash and Nagad to the shop checkout. It is a FalconCMS Pro plugin. It needs the Falcon Shop plugin and FalconCMS 2.8.1 or newer.</p><p>Turn it on under <strong>Admin → Plugins</strong>. Its settings are under <strong>Admin → eCommerce → BD Payments</strong>.</p><p>Each gateway works in one of two modes:</p><table tabindex="0"><thead><tr><th>Mode</th><th>How the customer pays</th><th>Who confirms the payment</th></tr></thead><tbody><tr><td><strong>Manual</strong></td><td>Sends money to your bKash / Nagad number, then enters the number they paid from and the TrxID at checkout</td><td>You, from the order screen</td></tr><tr><td><strong>API</strong></td><td>Is sent to the official bKash or Nagad payment page and pays with PIN &amp; OTP</td><td>The shop, automatically, after checking with bKash / Nagad</td></tr></tbody></table><p>Manual mode needs only a bKash or Nagad account. API mode needs a merchant account and its API credentials.</p><h2 id="manual-mode" tabindex="-1">Manual mode <a class="header-anchor" href="#manual-mode" aria-label="Permalink to &quot;Manual mode&quot;">​</a></h2><h3 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h3><p>On the <strong>bKash</strong> or <strong>Nagad</strong> tab, choose <strong>Manual Mode</strong> and fill in:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td>Enable</td><td>Shows the gateway at checkout</td></tr><tr><td>Title</td><td>The name customers see (e.g. <code>bKash</code>)</td></tr><tr><td>Account Type</td><td>Personal (Send Money), Merchant (Payment) or Agent (Cash In)</td></tr><tr><td>Account Number</td><td>The number customers send money to. Bangladeshi mobile numbers only (013–019, 11 digits)</td></tr><tr><td>Customer Instructions</td><td>Shown on the checkout when the gateway is selected</td></tr></tbody></table><h3 id="at-checkout" tabindex="-1">At checkout <a class="header-anchor" href="#at-checkout" aria-label="Permalink to &quot;At checkout&quot;">​</a></h3><p>When the customer chooses bKash or Nagad, the checkout shows your number with a <strong>Copy</strong> button, your instructions, and two fields:</p><ul><li><strong>Sender number</strong>: the number they paid from.</li><li><strong>Transaction ID (TrxID)</strong>: the ID bKash or Nagad sent them after the payment.</li></ul><p>Both fields are checked as the customer types, and again on the server:</p><ul><li>The number field takes <strong>digits only</strong>. A letter or symbol is removed as it is typed or pasted, and the field says why. Too short, too long or a wrong operator (anything but 013–019) is shown live. <code>+880…</code> and Bangla digits (০১৭…) are accepted and saved as <code>01XXXXXXXXX</code>.</li><li>The TrxID must be 8–20 English letters and digits. It is saved in capitals.</li><li><strong>One TrxID pays for one order.</strong> A TrxID already used on another order is refused. A TrxID from a rejected payment can be used again.</li></ul><p>The order is placed as <strong>Pending</strong>. It is not marked paid until you check the payment.</p><h3 id="verifying-a-payment" tabindex="-1">Verifying a payment <a class="header-anchor" href="#verifying-a-payment" aria-label="Permalink to &quot;Verifying a payment&quot;">​</a></h3><p>Open the order. The <strong>bKash / Nagad</strong> box in the sidebar shows the sender number, the TrxID (with a copy button) and the amount to look for. Check them in your bKash or Nagad app, then:</p><ul><li><strong>Verify payment</strong> moves the order to <strong>Processing</strong> and records it as paid. The customer gets the usual status email.</li><li><strong>Reject</strong> moves the order to <strong>Failed</strong>.</li></ul><p>Moving the order with the normal status box works too (see <a href="#payment-status-follows-the-order">Payment status</a>).</p><h2 id="api-mode" tabindex="-1">API mode <a class="header-anchor" href="#api-mode" aria-label="Permalink to &quot;API mode&quot;">​</a></h2><h3 id="bkash-tokenized-checkout" tabindex="-1">bKash: Tokenized Checkout <a class="header-anchor" href="#bkash-tokenized-checkout" aria-label="Permalink to &quot;bKash: Tokenized Checkout&quot;">​</a></h3><p>On the <strong>bKash</strong> tab, choose <strong>Automated API Mode</strong> and enter the <strong>App Key</strong>, <strong>App Secret</strong>, <strong>API Username</strong> and <strong>API Password</strong> from your bKash merchant account. Leave <strong>Sandbox / Test Mode</strong> ticked while testing, and untick it for live payments.</p><h3 id="nagad-pgw" tabindex="-1">Nagad: PGW <a class="header-anchor" href="#nagad-pgw" aria-label="Permalink to &quot;Nagad: PGW&quot;">​</a></h3><p>On the <strong>Nagad</strong> tab, choose <strong>Automated API Mode</strong> and enter your <strong>Merchant ID</strong>, the <strong>Nagad PGW Public Key</strong> and your <strong>Merchant Private Key</strong>. Nagad&#39;s sandbox and live keys both come with a Nagad merchant account.</p><h3 id="how-an-api-payment-works" tabindex="-1">How an API payment works <a class="header-anchor" href="#how-an-api-payment-works" aria-label="Permalink to &quot;How an API payment works&quot;">​</a></h3><ol><li>The customer places the order and is sent to the bKash or Nagad payment page.</li><li>They pay with their wallet number, OTP and PIN.</li><li>They come back to your shop. The shop checks the payment with bKash or Nagad from the server.</li><li>The order is marked paid only if the provider confirms it. The payment must belong to this order, and be for at least the order total.</li></ol><p>Nothing in the return link can mark an order paid on its own. A cancelled or failed payment leaves the order pending, and the customer sees a message on the order confirmation page.</p><p>The callback URLs are shown on each tab. The plugin handles them; there is nothing to set up.</p><div class="tip custom-block"><p class="custom-block-title">Testing bKash without a merchant account</p><p>bKash publishes sandbox credentials for testing. Use them with <strong>Sandbox / Test Mode</strong> ticked:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>App Key</td><td><code>4f6o0cjiki2rfm34kfdadl1eqq</code></td></tr><tr><td>App Secret</td><td><code>2is7hdktrekvrbljjh44ll3d9l1dtjo4pasmjvs5vl5qr3fug4b</code></td></tr><tr><td>API Username</td><td><code>sandboxTokenizedUser02</code></td></tr><tr><td>API Password</td><td><code>sandboxTokenizedUser02@12345</code></td></tr></tbody></table><p>On the bKash payment page, use the test wallet <strong>01770618575</strong>, OTP <strong>123456</strong> and PIN <strong>12121</strong>. The sandbox accepts only bKash&#39;s test wallets. Any other number shows <em>&quot;The input wallet is not eligible&quot;</em>. No real money moves.</p><p>Nagad has no public sandbox credentials.</p></div><h3 id="saved-credentials" tabindex="-1">Saved credentials <a class="header-anchor" href="#saved-credentials" aria-label="Permalink to &quot;Saved credentials&quot;">​</a></h3><p>The bKash App Secret and API Password, and the Nagad private key, are stored encrypted. After you save them, the field shows only part of the saved value (for example <code>2is7hdktrek••••••••</code>), never the whole of it. Leave the field blank to keep it, or tick <strong>Remove saved value</strong> to delete it.</p><h2 id="payment-status-follows-the-order" tabindex="-1">Payment status follows the order <a class="header-anchor" href="#payment-status-follows-the-order" aria-label="Permalink to &quot;Payment status follows the order&quot;">​</a></h2><p>Each bKash or Nagad payment has a status on the <strong>Payment Logs</strong> tab. It changes with the order, however the order is moved: the status box, a bulk action, or the Verify / Reject buttons.</p><table tabindex="0"><thead><tr><th>Order status</th><th>Payment status</th></tr></thead><tbody><tr><td>Processing, Confirmed, Packing, Packed, Delivering, Delivered, Completed</td><td><strong>Completed</strong>. A manual order is also recorded as paid</td></tr><tr><td>Cancelled</td><td>Cancelled</td></tr><tr><td>Failed</td><td>Failed</td></tr><tr><td>Refunded, Partially Refunded</td><td>Refunded</td></tr><tr><td>Pending, On Hold</td><td>Pending (manual payments; a confirmed API payment stays Completed)</td></tr></tbody></table><p>The <strong>Payment Logs</strong> tab lists the latest 25 payments with gateway, mode, order, amount, TrxID, sender number, payment status and order status.</p><h2 id="uninstalling" tabindex="-1">Uninstalling <a class="header-anchor" href="#uninstalling" aria-label="Permalink to &quot;Uninstalling&quot;">​</a></h2><p>Uninstalling keeps your settings and payment log, unless you tick <strong>Also delete all of its data</strong>. With that ticked, every bKash and Nagad setting (including the saved credentials) and the payment log are deleted.</p>',38)])])}const p=e(r,[["render",s]]);export{m as __pageData,p as default};
